const email = $input.first().json;

const sender = typeof email.from === 'string'
  ? email.from
  : email.from?.value?.[0]?.address || email.headers?.from || '';

return [{
  json: {
    externalId: email.id,
    threadId: email.threadId,
    title: email.subject || '(no subject)',
    sender,
    originalContent: email.text || email.snippet || '',
    eventCreatedAt: email.date ? new Date(email.date).toISOString() : new Date().toISOString(),
    sourceUrl: `https://mail.google.com/mail/u/0/#all/${email.threadId || email.id}`,
  },
}];

