parameters.jsCode:
const email = $('Normalize Gmail Email').first().json;
const gemini = $input.first().json;
const text = gemini.text || gemini.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) throw new Error('Gemini returned no summary');

const { summary } = JSON.parse(text.replace(/```json|```/g, '').trim());

return [{
  json: {
    source: 'gmail',
    activity_type: 'email',
    external_id: email.externalId,
    title: email.title,
    sender: email.sender,
    summary,
    original_content: email.originalContent,
    source_url: email.sourceUrl,
    event_created_at: email.eventCreatedAt,
    metadata: { thread_id: email.threadId, subject: email.title },
  },
}];
